const b = $input.first().json;
const pickName = (v) => (v && typeof v === 'object' ? (v.nome || v.modello || v) : v);
const prezzo = Number(String(b.prezzo ?? '').replace(',', '.'));
if (!b.regione || !b.auto || !b.intervento || !Number.isFinite(prezzo) || prezzo <= 0) {
  throw new Error('Payload non valido: servono regione, auto, intervento e prezzo > 0');
}
const auto = (b.auto && typeof b.auto === 'object')
  ? { modello: String(b.auto.modello || ''), motore: String(b.auto.motore || '') }
  : { modello: String(b.auto || ''), motore: '' };
return [{
  regione: String(pickName(b.regione)),
  auto,
  intervento: String(pickName(b.intervento)),
  prezzo,
  note: String(b.note || '').slice(0, 280)
}];

