const TARIFFE = { 'Lombardia': 42, 'Lazio': 40, 'Campania': 34, 'Sicilia': 33, 'Veneto': 40, 'Piemonte': 39, 'Emilia-Romagna': 40, 'Toscana': 38, 'Puglia': 34, 'Liguria': 39, 'Marche': 36, 'Abruzzo': 34, 'Calabria': 32, 'Sardegna': 34, 'Friuli-Venezia Giulia': 38, 'Trentino-Alto Adige': 41, 'Umbria': 35, 'Basilicata': 32, 'Molise': 32, "Valle d'Aosta": 39 };
const RICAMBI_AUTO = { 'default': 95, 'Fiat Panda': 85, 'Volkswagen Golf': 130, 'Renault Clio': 95, 'Toyota Yaris': 110, 'Fiat 500': 88, 'Dacia Sandero': 75, 'Peugeot 208': 98, 'Ford Fiesta': 102 };
const INTERVENTI = { 'Tagliando Completo': { ore: 1.5, extra: 60 }, 'Freni (pastiglie + dischi)': { ore: 2.0, extra: 90 }, 'Cinghia Distribuzione': { ore: 3.5, extra: 120 }, 'Frizione': { ore: 4.5, extra: 180 }, 'Batteria': { ore: 0.5, extra: 100 } };
const inp = $input.first().json;
let ai = null;
try {
  const raw = $('AI Stimatore').first().json.output;
  const m = String(raw).match(/\{[\s\S]*\}/);
  if (m) ai = JSON.parse(m[0]);
} catch (e) { ai = null; }
const num = (v) => (Number.isFinite(Number(v)) && Number(v) > 0 ? Number(v) : null);
const tariffa = (ai && num(ai.tariffa_oraria)) || TARIFFE[inp.regione] || 36;
const iv = INTERVENTI[inp.intervento] || { ore: 1.5, extra: 60 };
const ore = (ai && num(ai.ore_stimate)) || iv.ore;
const baseRicambi = RICAMBI_AUTO[inp.auto.modello] ?? RICAMBI_AUTO['default'];
const ricambi = Math.round((ai && num(ai.ricambi_stimati)) || (baseRicambi + iv.extra));
const manodopera = Math.round(ore * tariffa);
const stima = manodopera + ricambi;
const scostamento = Math.round(inp.prezzo - stima);
const pct = stima === 0 ? 0 : scostamento / stima;
const verdetto = pct <= 0.1 ? 'equo' : (pct <= 0.25 ? 'sopra-media' : 'anomalo');
const euro = (n) => '€ ' + Number(n).toFixed(2).replace('.', ',');
return [{
  manodopera, ricambi, stima, scostamento, verdetto,
  fonte: ai ? ('ai:' + String(ai.fonti || 'gpt')) : 'benchmark',
  messaggio: 'Buongiorno, ho confrontato il preventivo da ' + euro(inp.prezzo) + ' per ' + inp.intervento + ' su ' + inp.auto.modello + ' (' + inp.regione + ') con i benchmark (stima equa circa ' + euro(stima) + '). Potreste aiutarmi a capire la differenza? Grazie!'
}];

